-- space_sessions is write-hot: pre-create this index before deploy so the migration is a no-op and writes stay open:
--   CREATE INDEX CONCURRENTLY IF NOT EXISTS "v2_idx_space_sessions_shared_participant_user_uuids" ON "v2"."space_sessions" USING gin (("meta" -> 'participants' -> 'userUuids')) WHERE (("meta" -> 'participants' -> 'userUuids') -> 1) is not null or (("meta" -> 'participants' -> 'userUuids') ->> 0) <> coalesce("user_uuid", '');
CREATE INDEX IF NOT EXISTS "v2_idx_space_sessions_shared_participant_user_uuids" ON "v2"."space_sessions" USING gin (("meta" -> 'participants' -> 'userUuids')) WHERE (("v2"."space_sessions"."meta" -> 'participants' -> 'userUuids') -> 1) is not null or (("v2"."space_sessions"."meta" -> 'participants' -> 'userUuids') ->> 0) <> coalesce("v2"."space_sessions"."user_uuid", '');
